import json
from pathlib import Path
R=Path('/workspace/skill-library')
AFF="Original synthesis/processing recipe; not affiliated with any vendor named in the source. Recreate in browser/Web Audio (Polyrhythm Studio) or any DAW/synth with comparable modules; no presets, banks, impulse responses or samples copied."
DRUMS="Drums early (Matt's taste): if the track has drums, the kick/drum loop enters by about count 8 (roughly 10-12 s), with only the pad before that."
def S(n,a,t,e): return {"n":n,"action":a,"tool":t,"expect":e}
def mk(vid,title,sid,name,goal,pre,inp,out,cons,steps,ver,tags):
    d={"schema_version":"1.0","id":sid,"name":name,"goal":goal,"domain":"cinematic-synth",
       "source":{"kind":"youtube-transcript","video_id":vid,"url":f"https://www.youtube.com/watch?v={vid}","title":title,"transcript":"youtube-provided",
                 "distilled_path":f"distilled/{vid}/agent-skill-{sid}.json","batch":"2026-11-04-morning-hunt"},
       "prerequisites":pre,"inputs":inp,"outputs":out,"constraints":[AFF]+cons+[DRUMS],"steps":steps,"verification":ver,
       "tags":tags+["portable","steady-pitch","cinematic-synth"],"curriculum_ids":["curriculum-cinematic-hybrid-synth"],"mcp_resource":f"skill://{sid}"}
    p=R/'distilled'/vid; p.mkdir(parents=True,exist_ok=True)
    (p/f'agent-skill-{sid}.json').write_text(json.dumps(d,indent=2,ensure_ascii=False)+"\n"); print(p/f'agent-skill-{sid}.json')


mk("TosV3erGfsg","Sound Design - Ambient Pads and Atmospheres","start-bright-then-filter-pad",
 "Start-bright-then-filter pad: pick a harmonically rich (buzzy/bright) oscillator, odd unison 5-9, slow wavetable-position sweep, then low-pass to smooth it (keeping top-end headroom to automate back in), big low-cut reverb, low-cut EQ and a stereo imager to pull the pad around the listener; plus an attack-removed swell pad from any played source",
 "Make smooth, lush ambient pads that can still get bright on demand: start from a source with lots of high harmonics and remove highs with a synth filter (not an end-of-chain EQ), so the cutoff can be automated to bring brightness and air back for tension. Delta vs the brightness cluster: the 'rich source -> filter -> space' order, odd vs even unison as solid vs unstable, imager after big reverb to bring a distant pad back around the ears, and volume-swelling any played source (guitar, piano, vocal) so the reverb is fed only by the tone, not the attack.",
 ["Any synth with wavetable or saw oscillators, unison, a 12/18/24 dB low-pass and an LFO or envelope as mod source","Reverb with low-cut, EQ, stereo imager/width control","Optional: a recorded or sampled played source (guitar, piano, vocal) and a gain/volume envelope"],
 [{"name":"chords","type":"midi","description":"Chords, a counter-line or a single held note for the pad","required":True}],
 [{"name":"smooth_pad","type":"audio","description":"Smooth, wide pad whose brightness is controlled by one filter-cutoff lane"},{"name":"swell_pad","type":"audio","description":"Optional attack-free swell pad from a played source"}],
 ["Steady pitch: the source adds a slow fine-tune LFO for analog drift; leave it out (Matt prefers steady pitch). Use wavetable-position motion instead.","Brightness comes from the source and the filter cutoff, not from a late treble boost.","Cut pad low end (and low reverb) if another bass element is in the mix."],
 [S(1,"Set amp attack and release to about 400-500 ms each as a starting point, then tailor to the part.","Amp envelope","Notes fade in and out softly"),
  S(2,"Choose a bright, buzzy, harmonically rich oscillator (a saw, or a PWM/analog-style wavetable). Try many; keep the one with the most high-end energy and character.","Oscillator","Raw tone sounds bright, even harsh"),
  S(3,"Unison: an odd voice count (5, 7 or 9) gives a solid centre voice with voices spread either side; below 5 is not lush, above 9 costs CPU. For a rougher 'organic' pad, use an even count (e.g. 4): no centre voice gives a slightly unstable, edgy quality. Detune stays static.","Unison","Lush wide tone (odd) or deliberately unstable tone (even)"),
  S(4,"Optional motion: route a slow LFO or long envelope to wavetable position so it sweeps gently through the table.","Mod matrix","Timbre morphs slowly; pitch stays fixed"),
  S(5,"Low-pass the tone inside the synth (12 or 18 dB/oct; 18 gives a more pronounced cutoff) until smooth, then raise volume to compensate. Use the filter rather than an EQ so the cutoff can be automated to reintroduce highs for builds.","Filter","Smooth pad with brightness available on one automation lane"),
  S(6,"Space: a very large reverb at high mix with plenty of low-cut (filter before or after reverb, either order works), then an EQ cutting excess low end and optionally a second reverb.","Reverb + EQ","Deep, distant, not rumbly"),
  S(7,"Add a stereo imager after the reverbs and A/B: without it the pad sits far in front; with it the pad wraps around the listener.","Stereo imager","Pad surrounds the listener"),
  S(8,"Swell variant: play chords or a melody on any source (guitar, piano, vocal), start slightly before the bar, and put a gain envelope first in the chain that rises from 0 at the bar so the attack is removed. Then low-cut EQ, imager, and reverb, which is now fed only by the swell.","Gain envelope + FX","Attack-free tone swells into reverb and decays into the next chord")],
 ["Filter-cutoff automation alone audibly moves the pad from smooth to bright (high harmonics exist in the source).","Odd-unison version sounds solid; even-unison version audibly rougher.","With imager on, the side level rises and the mono fold-down still keeps the pad.","Swell variant: no audible pluck transient before the reverb bloom.","No pitch modulation in the patch."],
 ["pad","brightness","air","filter","unison","stereo-width","reverb","ambient","swell"])

mk("UrpnB5YlGL8","This Will Change How You Mix Kick And Bass FOREVER","kick-bass-four-level-lock",
 "Kick+bass punch workflow in four levels: (1) duck the bass to the kick, (2) split sub (<~100-120 Hz, mono, no unison) from mid-bass and duck the sub harder, (3) lock sub phase (fixed oscillator start phase, set by oscilloscope and blind A/B, then micro-delay alignment), (4) light bus glue on kick+bass: subtle subharmonic saturation, ~30 ms-attack glue compressor at 1-2 dB, soft clip",
 "Make kick and bass a solid, consistent low-end foundation: measure how the combined level swings when bass notes overlap the kick, then fix it in order: ducking, a separate mono sub with heavier ducking, phase-consistent sub (no random oscillator phase, start phase and a tiny delay chosen to reinforce the kick's fundamental), then gentle kick+bass bus processing. Fills the 'kick+bass punch workflow' gap; delta vs bass/sidechain clusters: oscillator phase lock and sample-level alignment against the kick, checked on an oscilloscope.",
 ["DAW with sidechain/volume-shaper ducking, EQ, a per-track delay (ms/samples) and an oscilloscope","Synth with oscillator phase and phase-randomize controls","Bus with saturation, glue compressor and soft clipper"],
 [{"name":"kick","type":"audio","description":"Kick drum track","required":True},{"name":"bassline","type":"midi","description":"Bass part, some notes overlapping the kick","required":True}],
 [{"name":"locked_low_end","type":"audio","description":"Kick+bass with consistent combined level on every hit"}],
 ["Only do level 4 after levels 1-3; bus processing will not fix a bad kick/bass relationship.","Blind A/B every move (eyes closed, bypass/redo) because changes are small.","Sub stays mono with no unison; pitch is steady (no pitch modulation on the sub).","The kick choice itself matters most; swap the kick if it fights the track."],
 [S(1,"Mark bass notes that hit with the kick and those that overlap it. Check level and oscilloscope with kick solo vs kick+bass: overlapping notes make the combined peak swing.","Meter + oscilloscope","Inconsistency measured"),
  S(2,"Level 1: duck the bass on every kick (sidechain compressor or volume shaper). Draw the duck shape by hand if the kick's exact shape is too long, so the bass sits in the pocket.","Sidechain / volume shaper","Kick is clear on every hit"),
  S(3,"Level 2: duplicate the bass into sub and mid-bass. High-pass the mid-bass at about 120 Hz (no fundamental there); low-pass the sub at the same point and turn its unison off so it is mono. Duck the sub fully on the kick and the mid-bass only a little. With one instrument only, use multiband ducking (below ~100 Hz ducked, above not), knowing the unison sub will still phase-cancel.","EQ + sidechain","Sustained bass audible over the kick without low-end pumping"),
  S(4,"Level 3a: on the sub oscillator set phase randomization to 0 so every note starts at the same point in the waveform. Overlay kick and sub on the oscilloscope.","Synth oscillator phase","Every sub note looks identical (consistent, though maybe out of phase)"),
  S(5,"Level 3b: sweep the sub's fixed start phase while watching the summed waveform and listening; pick the setting where the sum is loudest and steadiest, confirming by blind A/B.","Oscilloscope + ears","No level dip when kick and sub sum"),
  S(6,"Level 3c: if the sub's cycles are slightly offset from the kick's, add a tiny track delay (fractions of a ms) to the bass to line the waveforms up; blind A/B.","Track delay","Tighter low end"),
  S(7,"Level 4: route kick and all bass layers to one bus. Add a small amount of low-end/subharmonic saturation (easy to overdo), then a glue compressor at about 30 ms attack for 1-2 dB gain reduction with make-up gain, then a soft clip. If more than ~2 dB is needed, fix earlier steps instead.","Bus saturation + glue compressor + soft clip","Kick and bass gel as one element")],
 ["Combined kick+bass peak level is the same on overlapping and non-overlapping hits (within ~1 dB).","Oscilloscope shows the kick and sub cycles reinforcing, not cancelling.","Sub track is mono below ~120 Hz.","Bus compressor gain reduction stays at about 1-2 dB."],
 ["bass","kick","punchy-bass","sub-bass","sidechain","phase","low-end","mix","ambient-kick-bass"])

mk("L0mST_BaaBA","How To Write Drums for ANY Electronic Music Genre","genre-drum-pattern-families-tempo-map",
 "Program drums for any electronic genre from one foundation (kick on 1, snare on 2 and 4): four-on-the-floor vs two-step (kick on 1 and the 'and' of 3) families, offbeat open hats and 16th closed hats, a tempo-to-genre map (house/techno 120-130, trance 138-150, garage 128-135, breaks 140-150, DnB 170-180, halftime dubstep/trap 140), set syncopation spots, uniform swing on every second 8th/16th, and 2/4-bar variations with a tom fill and crash",
 "Build a genre-appropriate drum pattern quickly by choosing a pattern family and tempo instead of starting from a blank grid, then add syncopation, swing and fills in a fixed order. Delta vs the drum-groove cluster: the explicit pattern-family x tempo map (same pattern implies different genres at different BPM), halftime conversion by doubling note lengths, named syncopation positions, and the rule that layered sounds on swung steps get identical offsets.",
 ["Drum sampler/drum rack with kick, snare, closed and open hat, 3 toms, crash, ride, clap, rim (any 909-style kit)","DAW piano roll on a 16th grid in 4/4"],
 [{"name":"genre","type":"string","description":"Target genre or tempo","required":True}],
 [{"name":"drum_pattern","type":"midi","description":"1-, 2- and 4-bar drum pattern with fill"}],
 ["Sound choice also sets the genre; the patterns here are rhythm templates.","Keep only a few fills/variations and repeat them for cohesion.","Drums early (Matt's taste): bring the pattern in by about count 8."],
 [S(1,"Foundation, 1 bar of 4/4 on a 16th grid: kick on the downbeat (beat 1), snare on the backbeats (beats 2 and 4).","Piano roll","Basic pulse"),
  S(2,"Four-on-the-floor family: kick on every beat, open hat on every offbeat (the third 16th of each beat), closed hats on every second 16th to fill gaps. Tempo map: 120-130 BPM house/techno (128 typical house), 130-140 techno to trance, 138 typical trance, 140-150 trance, 170-180 hardcore (mute the extra 16th hats at high tempo).","Piano roll + tempo","Same pattern reads as different genres by tempo"),
  S(3,"Two-step family: foundation plus one kick on the 'and' (offbeat) of beat 3; closed hats on the remaining 8th notes (open hats can swap in on some). Tempo map: high 120s to mid 130s garage, 140-150 breaks, 170-180 drum & bass (174 typical).","Piano roll + tempo","Garage/breaks/DnB skeleton"),
  S(4,"Halftime: at 140-150 BPM double every note length/position of the two-step (1 bar becomes 2) for dubstep; add 16th closed hats with varied velocity for trap.","Piano roll (x2 / stretch)","Halftime feel"),
  S(5,"Syncopation for four-on-the-floor: claps on the last 16th of beat 1 and the offbeat of beat 2, repeated per beat pair, or moved to the second 16th of a beat; the same rhythm can go on a low tom. For two-step: rims on the last 16th of beat 2 and the second 16th of beat 3, and on 16ths leading into snares; extra kicks on offbeats or 16ths depending on tempo.","Piano roll","Groove and forward momentum"),
  S(6,"Swing: delay every second 8th (8th swing) or every second 16th (16th swing) by the same amount. Every sound on a swung step (e.g. hat and clap together) must get the identical offset; or use the DAW's groove feature.","Piano roll / groove","Consistent skippy feel (garage/house)"),
  S(7,"Variation: duplicate to 2 bars and change the clap pattern in bar 2; duplicate to 4 bars and put a high-to-mid-to-low tom fill on syncopated 16ths in bar 4; crash on the downbeat of bar 1 and rides on every beat at low velocity.","Piano roll","4-bar phrase that loops back cleanly")],
 ["Pattern family matches the genre: kick every beat (4otf) or kick on 1 and 3-and (two-step).","Tempo sits in the mapped range for the genre.","All notes on swung steps share one offset.","4-bar loop ends with a fill and restarts with a crash."],
 ["drums","drum-groove","genre-templates","four-on-the-floor","two-step","halftime","syncopation","swing","fills","music-theory"])

mk("xeuYUFZpOdA","How to make Atmospheric Liquid DNB Drums Step by Step [Beginner Tutorial]","atmospheric-liquid-dnb-break-layering",
 "Atmospheric liquid DnB break: 4-bar two-step kick/snare loop with the second kick quieter, kick EQ by dipping mids (not boosting lows/highs), one-shots tightened by shortening decay, a high-passed sliced break and percussive tops grouped and ducked to kick/snare, transient shaper + low-cut on tops, light glue compression into a soft clipper, and a very short no-pre-delay drum room",
 "Build an atmospheric drum & bass drum layer from a kick, a snare, percussive one-shots and a sliced break, so the break adds constant movement without clashing with the kick and snare, and peaks stay controlled for an easy loud master. Delta vs drum clusters: sample/break layering and bus processing (mid-dip kick focus, decay-shortened one-shots, tops ducked to kick/snare, soft-clipped glue bus, tiny drum room) rather than synthesis or pure programming.",
 ["DAW with sampler/one-shot mode or transient warping, slicing, groups","EQ, utility gain automation or sidechain, transient shaper, glue compressor with soft clip, short reverb on a return"],
 [{"name":"samples","type":"audio","description":"Kick, snare, rim/perc one-shots, shaker, a breakbeat loop","required":True}],
 [{"name":"dnb_drums","type":"audio","description":"Balanced atmospheric DnB drum loop at ~170-175 BPM"}],
 ["Processing is contextual: revisit it once the rest of the track exists.","Use original or licensed samples; no sample pack contents copied.","Drums early (Matt's taste): bring the loop in by about count 8."],
 [S(1,"Program a 4-bar two-step kick/snare loop; lower the second kick in each bar slightly so beat 1 is the strongest hit.","Piano roll","Phrased kick pattern"),
  S(2,"EQ the kick by dipping the mids (focuses the low and top without boosting), tame its top a little, and cut any low noise bump.","EQ","Focused, clean kick"),
  S(3,"Tighten percussive one-shots and the shaker by pitching where useful and shortening their decay (one-shot/gate mode), since reverb is added later.","Sampler decay","Short, tight hits"),
  S(4,"Bring in a break: tighten its decay, slice it, rearrange slices to fit the kick/snare rhythm, and high-pass it so it only adds top-end movement.","Slicing + HPF","Constant rhythm over the main hits"),
  S(5,"Group all top elements (break, percs, shaker). Duck the group on kick and snare (utility gain automation or sidechain) so tops never clash with the focal transients.","Group + ducking","Kick and snare stay clear"),
  S(6,"On the tops group: a transient shaper, then an EQ that removes any low bleed and rolls off harsh highs.","Transient shaper + EQ","Tops crisp, not abrasive"),
  S(7,"Drum bus: glue compressor with light compression and soft clip on, driving into the clipper so no spiky transient peaks too hard; then balance kick, snare and tops (levels change the compression).","Glue compressor + soft clip","Even peaks, easy to master loud"),
  S(8,"Send to a very short drum-room reverb with no pre-delay and short decay.","Reverb return","Drums gain life without long tails masking them")],
 ["Beat 1 kick is louder than the second kick.","Tops are audibly ducked on kick and snare hits.","No transient spikes above the clipper ceiling.","Reverb tail is short enough that hits stay distinct."],
 ["drums","dnb","liquid-dnb","breakbeat","layering","sidechain","soft-clip","drum-bus","atmospheric"])
